function download(name:string,content:string,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function parseCsv(text:string){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV has an unclosed quote.');row.push(cell);if(row.some(Boolean))rows.push(row);if(rows.length<2)throw new Error('The file needs a header row and at least one vehicle.');const keys=rows.shift()!.map(s=>s.trim().replace(/^\uFEFF/,'').toLowerCase().replace(/[ _-]/g,''));return rows.map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]?.trim()||''])));}
