function Empty({icon:Icon=CarFront,title,body,action}:{icon?:any;title:string;body:string;action?:ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={25}/></span><h3>{title}</h3><p>{body}</p>{action}</div>}
function Stat({label,value,detail,icon:Icon,tone='green'}:{label:string;value:ReactNode;detail:ReactNode;icon:any;tone?:string}){return <div className="stat"><div className="stat-top"><span>{label}</span><Icon size={17}/></div><strong>{value}</strong><div className={'stat-detail '+tone}>{detail}</div></div>}
function Photo({v,large=false}:{v:Vehicle;large?:boolean}){return imageOf(v)?<img className={large?'vehicle-hero':'vehicle-thumb'} src={imageOf(v)} alt={vehicleTitle(v)} onError={e=>{e.currentTarget.style.visibility='hidden'}}/>:<div className={large?'vehicle-hero photo-placeholder':'vehicle-thumb photo-placeholder'}><CarFront size={large?48:24}/></div>}
function FormField({label,value,onChange,type='text',placeholder,required=false}:{label:string;value:any;onChange:(v:any)=>void;type?:string;placeholder?:string;required?:boolean}){return <label className="field"><span>{label}{required&&' *'}</span><input type={type} value={value??''} onChange={e=>onChange(e.target.value)} placeholder={placeholder} min={type==='number'?0:undefined} step={type==='number'?'any':undefined} required={required}/></label>}

