 const workspaceVersion=useRef(0),workspaceLoaded=useRef(false);
 // Only an initial load failure blocks the workspace; later refresh failures keep usable data.
 const load=useCallback(async()=>{if(!workspaceLoaded.current)setLoadError('');try{const r=await fetch('/api/workspace',{cache:'no-store'});const j:any=await r.json();if(!r.ok)throw new Error(j.error||'Could not load workspace');workspaceLoaded.current=true;setWs(j);setLoadError('');return true;}catch(e:any){if(!workspaceLoaded.current)setLoadError(e.message);return false;}finally{setLoading(false);}},[]);
 useEffect(()=>{load()},[load]);
 // Background reads update comparisons without resetting selected vehicles or form state.
 useEffect(()=>{
  let active=true,pending:AbortController|null=null;
  async function refreshSavedWorkspace(){
   if(pending)return;
   const controller=new AbortController(),version=workspaceVersion.current;pending=controller;
   try{const response=await fetch('/api/workspace',{cache:'no-store',signal:controller.signal});if(!response.ok)return;const data:Workspace=await response.json();if(active&&version===workspaceVersion.current){workspaceLoaded.current=true;setWs(data);setLoadError('');setLoading(false)}}catch{}finally{if(pending===controller)pending=null}
  }
  const onFocus=()=>{void refreshSavedWorkspace()};
  const timer=window.setInterval(()=>{if(document.visibilityState==='visible')void refreshSavedWorkspace()},60000);
  window.addEventListener('focus',onFocus);
  return()=>{active=false;pending?.abort();window.clearInterval(timer);window.removeEventListener('focus',onFocus)};
 },[]);
 useEffect(()=>{setPage(1)},[search,condition,brand,tab,sort,inventorySide,inventoryStatus]);
 useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(''),7000);return()=>clearTimeout(id)},[notice]);
 useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape'){setSelected(null);setModal(null);setMobileNav(false);}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
 const accessSignature=JSON.stringify(ws?.access);const lastAccess=useRef(accessSignature);useEffect(()=>{if(lastAccess.current!==accessSignature){setSelected(null);setModal(null);setMessagesOpen(false);lastAccess.current=accessSignature}},[accessSignature]);
 const access=ws?.access;const allowed=(t:string)=>t==='Hub'||(t==='Users & Access'?!!access?.owner:can(access,tabModule[t]));
