 const launchOnce=useRef(false);useEffect(()=>{if(!ws||launchOnce.current)return;launchOnce.current=true;const params=new URLSearchParams(window.location.search),vin=params.get('vin');if(vin&&can(ws.access,'inventory')){const v=ws.vehicles.find(v=>v.vin===vin);if(v){setTab('Inventory');setSelected(v)}}if(params.get('app')==='keys'&&can(ws.access,'keys'))setTab('Keys & Operations');},[ws]);
 const selectedVehicle=selected?vehicles.find(vehicle=>vehicle.vin===selected.vin)||selected:null;
