 const photosMissing=active.filter(v=>!imageOf(v)),priceMissing=active.filter(v=>!v.price||Number(v.price)<=0),descMissing=active.filter(v=>!v.description),costKnown=active.filter(v=>num(meta(v).cost)!==null);
 const tasks=records.filter(r=>r.kind==='task'),appraisals=records.filter(r=>r.kind==='appraisal'),comps:RecordEntry[]=[],sourcing=records.filter(r=>r.kind==='sourcing');
