 const filtered=useMemo(()=>{let a=vehicles.filter(v=>{const m=rec(v.vin)?.data||{};const matches=!search||[v.vin,v.stock,vehicleTitle(v),v.dealer].join(' ').toLowerCase().includes(search.toLowerCase());const cond=tab==='Inventory'?(inventorySide==='Used'?used(v):!used(v))&&(inventoryStatus==='Sold'?m.status==='sold':m.status!=='sold'&&(inventoryStatus!=='Wholesale'||m.status==='wholesale')):condition==='All inventory'||condition==='Pre-owned'&&used(v)||condition==='New'&&!used(v)||condition==='Sold'&&m.status==='sold'||condition==='Wholesale'&&m.status==='wholesale';return matches&&cond&&(brand==='All brands'||v.make===brand)&&(tab!=='Wholesale'||m.status==='wholesale')&&(tab==='Inventory'||condition==='Sold'||m.status!=='sold');});if(sort==='price-low')a.sort((a,b)=>(num(a.price)??Infinity)-(num(b.price)??Infinity));if(sort==='price-high')a.sort((a,b)=>(num(b.price)??-Infinity)-(num(a.price)??-Infinity));if(sort==='miles')a.sort((a,b)=>(num(a.mileage)??Infinity)-(num(b.mileage)??Infinity));if(sort==='year')a.sort((a,b)=>(b.year||0)-(a.year||0));if(sort==='stock-age')a.sort((a,b)=>(days(rec(b.vin)?.data.acquiredDate)||0)-(days(rec(a.vin)?.data.acquiredDate)||0));return a;},[vehicles,records,search,condition,brand,sort,tab,inventorySide,inventoryStatus]);
 async function save(id:string,kind:string,data:any,revision?:number){workspaceVersion.current++;const r=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,kind,data,revision})});const j:any=await r.json();if(!r.ok)throw new Error(j.error||(r.status===409?'This record changed. Refresh and try again.':'Save failed'));workspaceVersion.current++;setWs(w=>w?{...w,records:[...w.records.filter(x=>!(x.id===id&&x.kind===kind)),j.record]}:w);return j.record;}
 async function remove(r:RecordEntry){workspaceVersion.current++;setBusy(r.id);try{const res=await fetch('/api/records',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:r.id,kind:r.kind,revision:r.revision})});const j:any=await res.json();if(!res.ok)throw new Error(j.error||'Delete failed');workspaceVersion.current++;setWs(w=>w?{...w,records:w.records.filter(x=>!(x.id===r.id&&x.kind===r.kind))}:w);setNotice('Record deleted.');}catch(e:any){setNotice(e.message)}finally{setBusy('')}}
 async function refreshData(){setBusy('refresh');try{if(await load())setNotice('Latest saved inventory and pricing data loaded.');}finally{setBusy('')}}
 async function sync(){setBusy('sync');try{const r=await fetch('/api/sync',{method:'POST'});const j:any=await r.json();if(!r.ok)throw new Error(j.error||'Source could not be refreshed. Your saved inventory is intact.');await load();setNotice(j.message||`Inventory refreshed. ${j.count??j.imported??''} vehicles received.`);}catch(e:any){setNotice(e.message)}finally{setBusy('')}}
 async function importFile(file:File,kind='inventory'){setBusy('import');setImportError('');try{if(kind==='comp'){const rows=parseCsv(await file.text()).filter(r=>r.price&&r.make&&r.model).map((r,i)=>{const flag=String(r.certified||'').trim().toLowerCase(),certified=/^(true|yes|1)$/.test(flag)?true:/^(false|no|0)$/.test(flag)?false:null;if(flag&&!/^(true|yes|1|false|no|0|null|unknown)$/.test(flag))throw new Error('Invalid advertised certification in comparison row '+(i+2)+'. Use true/yes/1, false/no/0, or leave blank.');const scope=String(r.scope||'expanded').trim().toLowerCase();if(!['regional','expanded'].includes(scope))throw new Error('Invalid source sample in comparison row '+(i+2)+'. Use regional or expanded.');const observedAt=r.observedat||new Date().toISOString();if(!Number.isFinite(Date.parse(observedAt)))throw new Error('Invalid observedAt in comparison row '+(i+2)+'.');const price=Number(r.price.replace(/[$,]/g,''));if(!(Number.isFinite(price)&&price>0))throw new Error('Enter a positive asking price in comparison row '+(i+2)+'.');return {vin:r.vin?.toUpperCase()||'',year:Number(r.year)||null,make:r.make,model:r.model,trim:r.trim,mileage:num((r.mileage||r.miles||'').replace(/,/g,'')),price,url:r.url||'',condition:r.condition||'Used',source:r.source||r.dealer||file.name,dealer:r.dealer||r.source||'',city:r.city||'',state:(r.state||'').toUpperCase(),certified,scope,observedAt,importFile:file.name,manuallySupplied:true};});let count=0;for(const row of rows){await save(crypto.randomUUID(),'comp',row);count++;}setNotice(`Added ${count} manually supplied comparable listings.`);return;}let arr:any[];const text=await file.text();if(file.name.toLowerCase().endsWith('.json')){const j=JSON.parse(text);arr=Array.isArray(j)?j:j.vehicles;if(!Array.isArray(arr))throw new Error('JSON must contain a vehicles array.');}else arr=parseCsv(text).map(r=>({vin:r.vin?.toUpperCase(),stock:r.stock||r.stocknumber,year:Number(r.year)||undefined,make:r.make,model:r.model,trim:r.trim,condition:r.condition||r.type||'Used',price:r.price?Number(r.price.replace(/[$,]/g,'')):null,mileage:(r.mileage||r.miles)?Number((r.mileage||r.miles).replace(/,/g,'')):null,exterior:r.exterior||r.exteriorcolor,interior:r.interior||r.interiorcolor,photos:(r.photos||r.image||r.photo||'').split('|').filter(Boolean),url:r.url,description:r.description,dealer:r.dealer||'Betten Imports'}));const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({vehicles:arr,source:file.name,complete:false})});const j:any=await r.json();if(!r.ok)throw new Error(j.error||'Import failed');await load();setNotice(`Imported ${j.count??j.imported??arr.length} vehicles. Existing dealership work was preserved.`);}catch(e:any){setImportError(e.message);setNotice(e.message)}finally{setBusy('')}}
 async function importDealerFile(file:File){setBusy('dealer-import');setImportError('');try{setDealerSkipped([]);const parsed=/\.xlsx$/i.test(file.name)?await readDealerExcel(file,dealerReportDate):prepareDealerRows(parseCsv(await file.text()).filter(r=>Object.values(r).some(v=>String(v).trim())));const rows=parsed.rows;setDealerSkipped(parsed.skippedRows);const r=await fetch('/api/dealer-import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows,overwrite:false,skipUnknown:true})});const j:any=await r.json();if(!r.ok)throw new Error(j.error||'Dealer data import failed');setDealerSkipped([...parsed.skippedRows,...(j.skippedUnknownVins||[]).map((vin:string)=>({row:null,identifier:vin,vehicle:'Unmatched inventory VIN',stock:'',reason:'VIN not found in current or archived inventory; import that vehicle first.'}))]);await load();setNotice(j.message||`Updated ${j.updated??0} vehicle workspaces; existing values were preserved.`);}catch(e:any){setImportError(e.message);setNotice(e.message)}finally{setBusy('')}}
