 function exportCsv(){const columns=['vin','stock','year','make','model','trim','condition','price','mileage','dealer','url'];download('betten-inventory.csv',[columns.map(csvEscape).join(','),...filtered.map(v=>columns.map(k=>csvEscape(v[k])).join(','))].join('\r\n'),'text/csv');}
