function safeUrl(url:any){try{const u=new URL(String(url));return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function landedCost(m:any){if(num(m.cost)===null)return null;return Number(m.cost)+(num(m.buyFees)||0)+(num(m.transport)||0)+(num(m.otherCost)||0)+(num(m.reconActual)??num(m.reconEstimate)??0)}

