 const [form,setForm]=useState<any>(record?.data||{}),[pane,setPane]=useState(can(access,'pricing')?'Pricing':'Specifications'),[saving,setSaving]=useState(false),[error,setError]=useState(''),[photoIndex,setPhotoIndex]=useState(0),[allFeatures,setAllFeatures]=useState(false);
 const paneModules:Record<string,string>={'Vehicle Info':'inventory','Research':'inventory',Pricing:'pricing','Book Values':'pricing',Media:'merchandising','Window Stickers':'merchandising',Lifecycle:'recon','Financials':'financials',Specifications:'inventory',Wholesale:'wholesale',Notes:'financials'};const paneAllowed=(p:string)=>p==='Vehicle Log'?!!access?.owner:can(access,paneModules[p]);
