 {pane==='Merchandising'&&<><div className="form-section-title"><h3>Imported listing checklist</h3><p>Review the source website before deciding what needs updating.</p></div>{[['Asking price',!!v.price],['Vehicle photos',!!imageOf(v)],['Listing description',!!v.description],['Equipment list',!!v.features?.length]].map(([label,ok])=><div className="checklist-row" key={String(label)}><span>{label}</span><Badge tone={ok?'green':'amber'}>{ok?'Imported':'Not imported'}</Badge></div>)}<div className="section-divider"/><div className="inline-heading"><h3>Dealership description draft</h3><button className="text-button" onClick={draftDescription}><FileText size={14}/>Build from details</button></div><p className="help-text">Drafts use imported vehicle facts. Review accuracy before publishing through your website provider.</p><label className="field"><span>Description draft</span><textarea rows={10} value={form.merchandisingDescription||''} onChange={e=>update('merchandisingDescription',e.target.value)} placeholder="Prepare a description for your listing…"/></label><button className="button" disabled={!form.merchandisingDescription} onClick={async()=>{await navigator.clipboard.writeText(form.merchandisingDescription);onNotice('Description copied for review and publishing.')}}>Copy description</button></>}
 {pane==='Wholesale'&&<><div className="form-section-title"><h3>Wholesale disposition plan</h3><p>Track your team's plan. No vehicle is submitted to an auction by this application.</p></div><label className="checkbox-row"><input type="checkbox" checked={form.status==='wholesale'} onChange={e=>update('status',e.target.checked?'wholesale':'retail')}/><span>Mark as a wholesale candidate</span></label><div className="form-grid"><FormField label="Channel / auction" value={form.wholesaleChannel} onChange={x=>update('wholesaleChannel',x)} placeholder="Auction or buyer"/><label className="field"><span>Wholesale status</span><select value={form.wholesaleStatus||'Candidate'} onChange={e=>update('wholesaleStatus',e.target.value)}>{['Candidate','Approved','Listed externally','In transit','Sold','Settled'].map(s=><option key={s}>{s}</option>)}</select></label><FormField label="Reserve / floor" type="number" value={form.wholesaleReserve} onChange={x=>update('wholesaleReserve',x)}/><FormField label="Final proceeds" type="number" value={form.wholesaleProceeds} onChange={x=>update('wholesaleProceeds',x)}/></div></>}
