function LocalPricing({vehicles,onOpen,embedded=false,onApply}:any){
 const [radius,setRadius]=useState(()=>{try{const saved=localStorage.getItem('betten.market.radius')||'';return ['','50','100','200','300','500','1000','2000'].includes(saved)?saved:''}catch{return ''}}),[years,setYears]=useState(0),[miles,setMiles]=useState(25000),[exactTrim,setExactTrim]=useState(true),[certifiedFilter,setCertifiedFilter]=useState<boolean|null>(null),[age,setAge]=useState(14);
 const v=vehicles[0],certifiedOnly=certifiedFilter??v?.certified===true;
 const classicControls=<><label>Distance from Betten<select aria-label="Comparison distance from Betten Imports" value={radius} onChange={e=>{setRadius(e.target.value);try{localStorage.setItem('betten.market.radius',e.target.value)}catch{}}}><option value="">Nationwide</option>{[50,100,200,300,500,1000,2000].map(n=><option key={n} value={n}>{n.toLocaleString()} miles</option>)}</select></label><p>Grand Rapids, MI · ZIP 49546</p><label>Model years<select aria-label="Comparison model years" value={years} onChange={e=>setYears(Number(e.target.value))}>{[0,1,2,3].map(n=><option key={n} value={n}>{n?'± '+n+' years':'Same year'}</option>)}</select></label><label>Mileage difference<select aria-label="Comparison mileage" value={miles} onChange={e=>setMiles(Number(e.target.value))}>{[10000,25000,50000,100000].map(n=><option key={n} value={n}>± {n.toLocaleString()} mi</option>)}</select></label><label>Observed within<select aria-label="Comparison freshness" value={age} onChange={e=>setAge(Number(e.target.value))}>{[7,14,30,60].map(n=><option key={n} value={n}>{n} days</option>)}</select></label><label className="criteria-check"><input type="checkbox" checked={exactTrim} onChange={e=>setExactTrim(e.target.checked)}/>Equivalent trim</label><label className="criteria-check"><input type="checkbox" checked={certifiedOnly} onChange={e=>setCertifiedFilter(e.target.checked)}/>Certified only</label><p>Equivalent name spellings are searched together. Refresh comparisons after changing criteria.</p></>;
 if(!v)return null;
 return <LiveMarket key={v.vin} vehicle={v} inventoryVehicle autoLookup={embedded} classicControls={classicControls} onApply={onApply} options={{radiusMiles:radius?Number(radius):null,maxYearDelta:years,maxMileageDelta:miles,maxAgeDays:age,exactTrim,certifiedOnly}}/>;
}
